_type": "none", "parking_slot": null}, {"contact_id": "fc5e44e5-39d3-47e0-a9cf-e325059128d5", "vehicle_type": "na", "parking_slot": null}, {"contact_id": "fc983cef-12a7-4823-a283-fd38fdc32bcb", "vehicle_type": "na", "parking_slot": null}, {"contact_id": "fce58ae7-e699-47d5-8d71-24db3412ce3a", "vehicle_type": "none", "parking_slot": null}, {"contact_id": "fd29953d-acd3-43f5-9334-67c4dedd676c", "vehicle_type": "na", "parking_slot": null}]$demo_parking$::jsonb)
), last_slot AS (
 SELECT COALESCE(MAX(substring(parking_slot FROM '^DEMO-P-([0-9]+)$')::bigint),0) AS last_number FROM public."SSP_Contact" WHERE parking_slot ~ '^DEMO-P-[0-9]+$'
), numbered AS (
 SELECT old, last_number+ROW_NUMBER() OVER (ORDER BY old->>'contact_id') AS slot_number FROM snapshots CROSS JOIN last_slot
), assignments AS (
 SELECT old, 'DEMO-P-' || lpad(slot_number::text,GREATEST(6,length(slot_number::text)),'0') AS slot FROM numbered
)
UPDATE public."SSP_Contact" c SET parking_slot = a.slot
FROM assignments a
WHERE c.contact_id::text = a.old->>'contact_id'
AND c.vehicle_type IS NOT NULL AND c.vehicle_type = a.old->>'vehicle_type'
AND c.parking_slot IS NOT DISTINCT FROM (a.old->>'parking_slot')
AND (c.parking_slot IS NULL OR btrim(c.parking_slot)='')
AND NOT EXISTS (SELECT 1 FROM public."SSP_Contact" other WHERE other.parking_slot=a.slot)
RETURNING c.contact_id,c.vehicle_type,c.parking_slot;
